/**
 * Single place that maps a third-party photo URL to its self-hosted copy
 * (ledger TD-09 / CM-08). The data file is generated by
 * scripts/self-host-images.mjs; licences and authors are recorded in
 * public/images/ATTRIBUTION.md and shown on /credits.
 *
 * Anything not in the table keeps its remote URL (and the card's gradient
 * behind it if the remote fails) — never an uncleared photo.
 */
import { SELF_HOSTED_COMMONS, SELF_HOSTED_UNSPLASH, type SelfHostedEntry } from './self-hosted-images.data';

const COMMONS_RE = /upload\.wikimedia\.org\/wikipedia\/commons\/(?:thumb\/)?[0-9a-f]\/[0-9a-f]{2}\/([^/?#]+)/;
const UNSPLASH_RE = /images\.unsplash\.com\/(photo-[0-9a-f-]+)/;
const OWN_ORIGIN_RE = /^https:\/\/(?:www\.)?darshya\.online(\/images\/[^?#]+)$/;

function decode(s: string): string {
  try {
    return decodeURIComponent(s);
  } catch {
    return s;
  }
}

export function selfHostedEntry(url: string | undefined | null): SelfHostedEntry | undefined {
  if (!url) return undefined;
  const c = COMMONS_RE.exec(url);
  if (c) return SELF_HOSTED_COMMONS[decode(c[1]!)];
  const u = UNSPLASH_RE.exec(url);
  if (u) return SELF_HOSTED_UNSPLASH[u[1]!];
  return undefined;
}

const BY_PATH: ReadonlyMap<string, SelfHostedEntry> = new Map(
  [...Object.values(SELF_HOSTED_COMMONS), ...Object.values(SELF_HOSTED_UNSPLASH)].flatMap((e) => {
    const rows: Array<[string, SelfHostedEntry]> = [[e.path, e]];
    for (const v of e.variants ?? []) rows.push([v.path, e]);
    return rows;
  }),
);

/**
 * The self-hosted file to serve for `url` at `width` CSS px, with the width of
 * the file actually served (the srcset descriptor). Slots take the smallest
 * variant (250 / 500) that covers `width`, else the full file. Accepts a remote URL OR an already
 * local /images/... path (what the API now returns).
 */
export function selfHostedFor(
  url: string | undefined | null,
  width: number,
): { url: string; width: number } | undefined {
  if (!url) return undefined;
  const e = url.startsWith('/images/') ? BY_PATH.get(url) : selfHostedEntry(url);
  if (!e) return undefined;
  for (const v of e.variants ?? []) if (width <= v.width) return { url: v.path, width: v.width };
  return { url: e.path, width: e.width };
}

/** Local path for a remote photo URL, or undefined when it is not self-hosted. */
export function selfHostedPath(url: string | undefined | null): string | undefined {
  return selfHostedEntry(url)?.path;
}

/** `https://darshya.online/images/x.webp` -> `/images/x.webp` (same file, origin-relative so dev/staging work). */
export function relativizeOwnImage(url: string): string {
  const m = OWN_ORIGIN_RE.exec(url);
  return m ? m[1]! : url;
}
